UPDATE document_index_version SET status='PUBLISHED',published_at=statement_timestamp()
WHERE id=#{claim.indexVersionId} AND document_id=#{claim.documentId}
AND status='VERIFIED' AND published_at IS NULL

UPDATE document_import_task SET status='SUCCEEDED',lease_owner=NULL,lease_until=NULL,
next_retry_at=NULL,last_error_code=NULL,last_error_message=NULL,updated_at=statement_timestamp()
WHERE id=#{claim.taskId} AND document_id=#{claim.documentId} AND index_version_id=#{claim.indexVersionId}
AND status='RUNNING' AND lease_owner=#{claim.leaseOwner} AND claim_epoch=#{claim.claimEpoch}
AND lease_until > statement_timestamp()
